_NONCE_SIZE = 12

_K_PARTS = [105, 254, 183, 27, 118, 223, 126, 246, 14, 56, 192, 75, 216, 146, 201, 241, 154, 8, 109, 77, 28, 161, 77, 12, 120, 59, 110, 79, 98, 254, 31, 157]
_K_MASK = [163, 42, 67, 170, 248, 90, 82, 79, 19, 16, 98, 234, 250, 78, 110, 48, 80, 205, 140, 108, 51, 90, 139, 84, 43, 158, 187, 181, 18, 145, 238, 35]

def _rebuild_key():
    parts = _K_PARTS
    mask = _K_MASK
    key = bytes(p ^ m for p, m in zip(parts, mask))
    return key

def _run():
    raw = base64.b85decode(_PAYLOAD)
    nonce, ciphertext = raw[:_NONCE_SIZE], raw[_NONCE_SIZE:]
    key = _rebuild_key()
    aesgcm = AESGCM(key)
    try:
        compressed = aesgcm.decrypt(nonce, ciphertext, None)
    except Exception:
        sys.stderr.write("Corrupted or tampered protected file.\n")
        sys.exit(1)
    raw_bytecode = zlib.decompress(compressed)
    code_obj = marshal.loads(raw_bytecode)
    exec(code_obj, {"__name__": "__main__", "__file__": __file__})

_run()
